<?php
declare(strict_types=1);
$isApiRequest = isset($_GET['action']) && $_GET['action'] !== '';
if (!$isApiRequest && strtoupper((string)($_SERVER['REQUEST_METHOD'] ?? 'GET')) === 'POST') {
    $rawBody = file_get_contents('php://input') ?: '';
    $jsonBody = json_decode($rawBody, true);
    $isApiRequest = is_array($jsonBody) && trim((string)($jsonBody['action'] ?? '')) !== '';
}
if ($isApiRequest) { require __DIR__ . '/V1/http.php'; exit; }
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chaba V1 Print Worker</title><style>body{font:15px Arial;background:#111827;color:#e5e7eb;margin:0;padding:28px}main{max-width:720px;margin:auto;background:#1f2937;border-radius:12px;padding:24px}.ok{color:#86efac}.warn{color:#fcd34d}.err{color:#fca5a5}#jobs{margin-top:18px;white-space:pre-wrap;background:#111827;padding:12px;border-radius:8px;min-height:80px}iframe{position:fixed;left:-10000px;top:-10000px;width:80mm;height:600px;border:0}</style></head><body><main><h1>Chaba V1 Print Worker</h1><div id="status" class="warn">Connecting to queue...</div><div id="jobs">Waiting for jobs...</div><iframe id="print-frame"></iframe></main><script>
(function(){const status=document.getElementById('status'),jobs=document.getElementById('jobs'),frame=document.getElementById('print-frame'),api='index.php';let busy=false;function line(s){jobs.textContent=new Date().toLocaleTimeString()+'  '+s+'\n'+jobs.textContent.slice(0,1800)}async function json(url){const r=await fetch(url,{cache:'no-store',credentials:'same-origin'});const p=await r.json();if(!r.ok||p.ok===false)throw Error(p.error||p.message||('HTTP '+r.status));return p}async function html(url){const r=await fetch(url,{cache:'no-store',credentials:'same-origin'});if(!r.ok)throw Error('Render HTTP '+r.status);return r.text()}async function printJob(job){const id=Number(job.queue_id||0),attempt=Number(job.print_attempts||0);status.className='warn';status.textContent='Rendering '+(job.label||job.print_type)+' #'+id;line('Rendering '+id);frame.srcdoc=await html(api+'?action=render&queue_id='+id);await new Promise(resolve=>{frame.onload=()=>{try{frame.contentWindow.focus();frame.contentWindow.print()}catch(e){}setTimeout(resolve,700)};setTimeout(resolve,5000)});await json(api+'?action=complete&queue_id='+id+'&print_attempts='+attempt);status.className='ok';status.textContent='Printed '+(job.label||job.print_type)+' #'+id;line('Printed '+id)}async function poll(){if(busy)return;busy=true;try{const p=await json(api+'?action=claim'),job=p.data&&p.data.job;if(!job){status.className='ok';status.textContent='Connected — waiting for jobs';return}try{await printJob(job)}catch(e){status.className='err';status.textContent='Print failed: '+e.message;line('Failed '+job.queue_id+': '+e.message);await json(api+'?action=fail&queue_id='+Number(job.queue_id)+'&print_attempts='+Number(job.print_attempts||0)+'&last_error='+encodeURIComponent(e.message))}}catch(e){status.className='err';status.textContent='Queue error: '+e.message;line(e.message)}finally{busy=false}}poll();setInterval(poll,3000)})();
</script></body></html>
